<script lang="ts">
 import {Button} from '$lib/components/ui/button';import {Play} from '@lucide/svelte';import {request} from '../api';
 let {asset,label='Selected video',previewEnabled=false}:{asset:any;label?:string;previewEnabled?:boolean}=$props();
 let preview=$state(''),busy=$state(false),error=$state('');
 const duration=$derived(asset.measured?`${(asset.duration_ms/1000).toLocaleString(undefined,{maximumFractionDigits:1})} seconds`:'Duration pending');
 const orientation=$derived(asset.measured?(asset.width===asset.height?'Square':asset.height>asset.width?'Portrait':'Landscape'):'Dimensions pending');
 async function openPreview(){busy=true;error='';try{const result=await request(`/media-assets/${asset.asset_id}/preview`);preview=result.url;}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<section class="source-summary" aria-label={label}>
 <div class="source-heading"><div><h2>{label}</h2><p>{asset.origin==='generated'?'Studio output':asset.filename||'Uploaded video'} · {asset.job_status||asset.status}</p></div>{#if previewEnabled}<Button variant="outline" size="sm" disabled={busy} onclick={openPreview}><Play class="size-3.5"/>{busy?'Preparing…':preview?'Refresh preview':'Preview source'}</Button>{/if}</div>
 <p class="source-measurement">{duration} · {orientation}{#if asset.measured} · {asset.width} × {asset.height}{/if}</p>
 <p class="source-version">Version {asset.asset_id}</p><details><summary>Source information</summary><dl><div><dt>Source version</dt><dd>{asset.asset_id}</dd></div>{#if asset.job_id}<div><dt>Studio job</dt><dd>{asset.job_id}</dd></div>{/if}<div><dt>Thumbnail</dt><dd>{asset.poster_available?'Generated frame ready':'Frame pending video inspection'}</dd></div><div><dt>Captions</dt><dd>{asset.captions_available?'Available · language not specified':'No captions added'}</dd></div></dl></details>
 {#if error}<p role="alert">{error}</p>{/if}{#if preview}<video src={preview} controls playsinline preload="metadata"><track kind="captions"/></video>{/if}
</section>
<style>.source-summary{margin:0 0 24px;padding:16px 0;border-block:1px solid var(--border);max-width:720px}.source-heading{display:flex;align-items:center;gap:16px;justify-content:space-between}.source-heading h2{font-size:13px;font-weight:600}.source-heading p,.source-measurement{font-size:12px;line-height:1.7;color:var(--muted-foreground);margin-top:7px}.source-version{font-size:11px;color:var(--muted-foreground);overflow-wrap:anywhere;margin-top:9px}.source-summary details{margin-top:10px;font-size:12px}.source-summary summary{cursor:pointer;color:var(--muted-foreground);padding:5px 0}.source-summary dl{display:grid;gap:10px;margin:12px 0}.source-summary dl>div{display:grid;grid-template-columns:100px minmax(0,1fr);gap:12px}.source-summary dt{color:var(--muted-foreground)}.source-summary dd{overflow-wrap:anywhere;line-height:1.6}.source-summary video{display:block;width:100%;max-height:300px;object-fit:contain;background:#000;margin-top:16px;border-radius:8px}.source-summary [role=alert]{font-size:12px;color:var(--destructive);margin-top:10px}@media(max-width:500px){.source-heading{align-items:start;flex-wrap:wrap}.source-heading :global(button){min-height:44px}}</style>
